      var smoke = new THREE.Mesh(smokeGeo, smokeMat);
      smoke.position.copy(car.mesh.position);
      smoke.position.y += random.float(0.5, 2);
      world3d.scene.add(smoke);
      effects.push({
        mesh: smoke,
        vx: random.float(-2, 2),
        vy: 1 + random.float(0, 3),
        vz: random.float(-2, 2),
        life: 2 + random.float(0, 2),
        maxLife: 3,
