      var newZ = player.z + Math.sin(player.angle) * moveY * spd * dt + Math.cos(player.angle) * moveX * spd * dt;

      var resolved = resolveCollision(newX, newZ, collisionBoxes);
      player.x = resolved.x;
      player.z = resolved.z;

      if (cars) {
        for (var i = 0; i < cars.length; i++) {
